import sympy
from sympy import abc
from functools import reduce

# Top-level setup
# Witnesses are expected to be of the form (n, I_gens, J_gens)
# representing the ring R = Z/nZ (if n is an integer) or R = k[x]/(n) (if n is a polynomial),
# and ideals I and J generated by I_gens and J_gens respectively.
# Generators can be single elements or lists of elements.

def conditions(witness) -> list[bool]:
    try:
        if len(witness) != 3:
            return [False, False, False]
        n, i, j = witness
        
        n_sym = sympy.sympify(n)
        if n_sym.is_number:
            try:
                n_sym = sympy.Integer(n_sym)
            except Exception:
                pass
                
        def get_gen(x):
            if isinstance(x, (list, tuple, set)):
                if not x:
                    return sympy.S.Zero
                return reduce(sympy.gcd, [sympy.sympify(g) for g in x])
            return sympy.sympify(x)
            
        i_gen = get_gen(i)
        j_gen = get_gen(j)
        
    except Exception:
        return [False, False, False]
        
    # H1: R is a local ring with a unique maximal ideal
    try:
        if n_sym.is_number:
            n_int = abs(int(n_sym))
            if n_int >= 2:
                from sympy.ntheory import factorint
                factors = factorint(n_int)
                h1 = (len(factors) == 1)
            else:
                h1 = False
        else:
            from sympy.polys.polytools import factor_list
            _, factors = factor_list(n_sym)
            h1 = (len(factors) == 1)
    except Exception:
        h1 = False
        
    # H2: I is a proper ideal of R
    try:
        g = sympy.gcd(i_gen, n_sym)
        if n_sym.is_number:
            h2 = (abs(int(g)) != 1)
        else:
            h2 = not g.is_number
    except Exception:
        h2 = False
        
    # ¬Q: The ideals I and J are comaximal
    try:
        g_ij = sympy.gcd(i_gen, j_gen)
        g_total = sympy.gcd(g_ij, n_sym)
        if n_sym.is_number:
            neg_q = (abs(int(g_total)) == 1)
        else:
            neg_q = bool(g_total.is_number and g_total != 0)
    except Exception:
        neg_q = False
        
    return [h1, h2, neg_q]

CONDITION_LABELS = [
    "H_1: R is a local ring with a unique maximal ideal",
    "H_2: I is a proper ideal of R",
    "¬Q: The ideals I and J are comaximal"
]

N_HYP = 2
NEG_Q_INDEX = 2